(mustShow, visualIntent='') {
  const intent = String(visualIntent ?? '').trim();
  const anchors = (Array.isArray(mustShow) ? mustShow : [])
    .map((anchor) => String(anchor ?? '').trim())
    .filter(Boolean);
  if (!intent || !anchors.length) return intent;

  const visibleActorPattern =
    /\b(?:person|people|man|woman|worker|operator|technician|user|hand|hands)\b/i;
  if (
    visibleActorPattern.test(intent) ||
    anchors.some((anchor) => visibleActorPattern.test(anchor))
  ) {
    return intent;
  }

  const hiddenFlowWords = (value) => String(value ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,' ')
    .split(/\s+/u)
    .filter(Boolean);
  const closedFlowHeads = new Set([
    'pipe','pipeline','conduit','duct','hose','tube',
    'valve','pump','filter','nozzle','engine','motor',
    'turbine','compressor'
  ]);
  const anchorHeads = anchors.map((anchor) => {
    const terms = hiddenFlowWords(anchor);
    return terms[terms.length - 1] || '';
  });
  const hiddenFlowThroughClosedObject =
    /\bflow(?:s|ed|ing)?\b[^.;]{0,80}\b(?:through|inside|within)\b/i.test(intent) &&
    anchorHeads.some((head) => closedFlowHeads.has(head)) &&
    !/\b(?:transparent|cutaway|exposed)\b/i.test(intent);

  const transientActionPattern =
    /\b(?:joining|binding|stapling|pinning|being\s+opened|opening|being\s+closed|closing|moving|sliding|aligning|engag(?:e|es|ed|ing)|inserting|pressing|pushing|pulling|locking|unlocking|fastening|unfastening|expand(?:s|ed|ing)?|expansion|hold(?:s|ing)?|held|stabiliz(?:e|es|ed|ing)|rotat(?:e|es|ed|ing|ion|ional(?:ly)?))\b/i;
  if (!transientActionPattern.test(intent) && !hiddenFlowThroughClosedObject) return intent;

  const closeUp = /\b(?:close[- ]?up|macro)\b/i.test(intent);
  const subject = anchors.length === 1
    ? anchors[0]
    : anchors[0] + ' with ' + anchors.slice(1).join(' and ');
  return (closeUp ? 'A close-up photo of ' : 'A clear photo of ') + subject + '.';
}
